  "content": "import typing as t

import pytest
from flask import Flask, Response


def test_after_request_callable_type() -> None:
    app = Flask(__name__)

    def my_func(response: Response) -> Response:
        return response

    # This should not raise a type error; the test passes if it runs without error.
    app.after_request(my_func)

    with app.test_client() as client:
        @app.route("/")
        def index() -> str:
            return "hello"

        resp = client.get("/")
        assert resp.status_code == 200
        assert resp.data == b"hello"
